<?php
require __DIR__.'/includes/auth.php';
if(($_SESSION['admin_role']??'admin')!=='admin'){http_response_code(403);exit('Forbidden');}
$db=db();
if($_SERVER['REQUEST_METHOD']==='POST'){
 admin_verify_csrf();$action=$_POST['action']??'';
 if($action==='save'){
  $id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$role=in_array($_POST['role']??'admin',['admin','editor'],true)?$_POST['role']:'editor';$status=isset($_POST['status'])?1:0;$password=$_POST['password']??'';
  if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL))admin_flash('','Name and valid email are required.');
  elseif($id){$q=$db->prepare('SELECT id FROM admins WHERE email=? AND id<>?');$q->execute([$email,$id]);if($q->fetch())admin_flash('','Email already exists.');else{$sql='UPDATE admins SET name=?,email=?,role=?,status=?'.($password!==''?',password_hash=?':'').' WHERE id=?';$args=[$name,$email,$role,$status];if($password!=='')$args[]=password_hash($password,PASSWORD_DEFAULT);$args[]=$id;$db->prepare($sql)->execute($args);admin_flash('success','Admin user updated.');}}
  else{if(strlen($password)<10)admin_flash('','New password must be at least 10 characters.');else{$q=$db->prepare('SELECT id FROM admins WHERE email=?');$q->execute([$email]);if($q->fetch())admin_flash('','Email already exists.');else{$db->prepare('INSERT INTO admins(name,email,password_hash,role,status) VALUES(?,?,?,?,?)')->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$role,$status]);admin_flash('success','Admin user created.');}}}
  header('Location: admin-users.php');exit;
 }
 if($action==='delete'){ $id=(int)($_POST['id']??0);if($id===(int)($_SESSION['admin_id']??0))admin_flash('','You cannot delete your own account.');else{$db->prepare('DELETE FROM admins WHERE id=?')->execute([$id]);admin_flash('success','Admin user deleted.');}header('Location: admin-users.php');exit;}
}
$edit=null;if(isset($_GET['edit'])){$q=$db->prepare('SELECT id,name,email,role,status FROM admins WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
$users=$db->query('SELECT id,name,email,role,status,created_at FROM admins ORDER BY id DESC')->fetchAll();
$page_title='Admin Users';require __DIR__.'/includes/header.php';
?>
<div class="card"><h3><?= $edit?'Edit Admin User':'Add Admin User' ?></h3><form class="form" method="post"><input type="hidden" name="csrf" value="<?=admin_csrf()?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=admin_e($edit['id']??0)?>"><div class="form-grid"><div class="field"><label>Name</label><input required name="name" value="<?=admin_e($edit['name']??'')?>"></div><div class="field"><label>Email</label><input required type="email" name="email" value="<?=admin_e($edit['email']??'')?>"></div><div class="field"><label>Role</label><select name="role"><option value="admin" <?=($edit['role']??'admin')==='admin'?'selected':''?>>Admin</option><option value="editor" <?=($edit['role']??'')==='editor'?'selected':''?>>Editor</option></select></div><div class="field"><label>Status</label><label><input type="checkbox" name="status" value="1" <?=((int)($edit['status']??1)===1)?'checked':''?>> Active</label></div><div class="field full"><label><?= $edit?'New Password (leave blank to keep current)':'Password (minimum 10 characters)' ?></label><input type="password" name="password" minlength="10" <?= $edit?'':'required' ?> autocomplete="new-password"></div></div><div class="actions"><button class="btn">Save User</button><?php if($edit):?><a class="btn gray" href="admin-users.php">Cancel</a><?php endif;?></div></form></div>
<div class="card"><h3>Administrators</h3><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=admin_e($u['name'])?></td><td><?=admin_e($u['email'])?></td><td><?=admin_e($u['role'])?></td><td><?=((int)$u['status']===1)?'Active':'Disabled'?></td><td><?=admin_e($u['created_at'])?></td><td><a class="btn gray" href="admin-users.php?edit=<?=$u['id']?>">Edit</a><?php if((int)$u['id']!==(int)$_SESSION['admin_id']):?><form method="post" style="display:inline" onsubmit="return confirm('Delete this admin user?')"><input type="hidden" name="csrf" value="<?=admin_csrf()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$u['id']?>"><button class="btn gray" type="submit">Delete</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div>
<?php require __DIR__.'/includes/footer.php';?>
